Definition art_lcdrain_a_mem (M : word -> option byte) (sp : Z) (raw : word) (ca ia c cnt h : Z) : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 8 "S90!1,1|600;!1+00|30;}4}8|48;|40;|508;|500;$M;R%~R1!1+2!1+0!1,12$sp;R+3$raw;R1$ca;R+3$ia;R+3$c;R+3$cnt;R+3$h;R+3!4'43!4'44!4'44!4'44!4'44!4'44!4'44!4'44#8!2'5#7!1,62!2'70#6!2'5#7!1,65,8!2'5#7!1,66,8!2'5#7!1,6|518;#4!2'5#7!1,6|510;,8!2'5#7!1,67,8!2'5#7!1,68,8!2'9#5!2':!1,6|610;#3!2'5#2#1").

